import{_ as s,a,c as e,b as l}from"./chunks/framework.b9WMfGr4.js";const u=JSON.parse('{"title":"11-TomcatWAR部署问题","description":"","frontmatter":{"title":"11-TomcatWAR部署问题"},"headers":[],"relativePath":"posts/开发经验/Spring与Java/11-TomcatWAR部署问题.md","filePath":"posts/开发经验/Spring与Java/11-TomcatWAR部署问题.md"}'),t={name:"posts/开发经验/Spring与Java/11-TomcatWAR部署问题.md"};function p(i,n,o,r,c,d){return a(),e("div",null,[...n[0]||(n[0]=[l(`<h3 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h3><p class="pseudo-heading"><strong>传统 JavaWeb 项目必须打包为 WAR</strong></p><ul><li>非 Spring Boot 项目没有内嵌 Tomcat，依赖外置容器（如 Tomcat）</li><li>WAR 包有严格的目录结构要求，<code>WEB-INF</code> 受保护，资源文件必须放在根目录</li><li>你之前的 <code>pom.xml</code> 写了 <code>&lt;packaging&gt;jar&lt;/packaging&gt;</code>，导致 Tomcat 无法识别 Web 资源</li></ul><p class="pseudo-heading"><strong>Jar 包部署的正确方式</strong></p><ul><li>若要以 Jar 包形式运行 Web 应用，必须是<strong>Spring Boot 项目</strong>（内置 Tomcat）</li><li>普通 JavaWeb 项目的 Jar 包只能作为<strong>依赖库</strong>，不能作为 Web 应用本身部署</li></ul><h3 id="解决方法" tabindex="-1">解决方法 <a class="header-anchor" href="#解决方法" aria-label="Permalink to &quot;解决方法&quot;">​</a></h3><p>修改 <code>pom.xml</code> 打包类型，把 <code>&lt;packaging&gt;jar&lt;/packaging&gt;</code> 改为 <code>&lt;packaging&gt;war&lt;/packaging&gt;</code>：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><button class="collapse-btn" title="折叠代码" aria-label="折叠代码"><svg class="collapse-icon" viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"></polyline></svg></button><span class="lang"></span><pre class="shiki shiki-themes github-light one-dark-pro vp-code" tabindex="0"><code><span class="line"><span>&lt;packaging&gt;war&lt;/packaging&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div><div class="code-collapsed-indicator"><span class="code-collapsed-text">已折叠代码，点击展开</span><svg class="expand-icon" viewBox="0 0 24 24" width="12" height="12" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"></polyline></svg></div></div><p>同时，建议添加 <code>maven-war-plugin</code> 确保打包正确（如果没有的话）：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><button class="collapse-btn" title="折叠代码" aria-label="折叠代码"><svg class="collapse-icon" viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"></polyline></svg></button><span class="lang"></span><pre class="shiki shiki-themes github-light one-dark-pro vp-code" tabindex="0"><code><span class="line"><span>&lt;build&gt;</span></span>
<span class="line"><span>    &lt;plugins&gt;</span></span>
<span class="line"><span>        &lt;plugin&gt;</span></span>
<span class="line"><span>            &lt;groupId&gt;org.apache.maven.plugins&lt;/groupId&gt;</span></span>
<span class="line"><span>            &lt;artifactId&gt;maven-war-plugin&lt;/artifactId&gt;</span></span>
<span class="line"><span>            &lt;version&gt;3.3.1&lt;/version&gt;</span></span>
<span class="line"><span>            &lt;configuration&gt;</span></span>
<span class="line"><span>                &lt;webResources&gt;</span></span>
<span class="line"><span>                    &lt;resource&gt;</span></span>
<span class="line"><span>                        &lt;directory&gt;web&lt;/directory&gt;</span></span>
<span class="line"><span>                    &lt;/resource&gt;</span></span>
<span class="line"><span>                &lt;/webResources&gt;</span></span>
<span class="line"><span>            &lt;/configuration&gt;</span></span>
<span class="line"><span>        &lt;/plugin&gt;</span></span>
<span class="line"><span>    &lt;/plugins&gt;</span></span>
<span class="line"><span>&lt;/build&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br></div><div class="code-collapsed-indicator"><span class="code-collapsed-text">已折叠代码，点击展开</span><svg class="expand-icon" viewBox="0 0 24 24" width="12" height="12" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"></polyline></svg></div></div>`,10)])])}const b=s(t,[["render",p]]);export{u as __pageData,b as default};
